    'occipital-anterior': surco('Surco occipital anterior', ['Anterior_occipital_sulcus']),
    'occipitales-superiores': surco('Giros occipitales superiores', ['Superior_occipital_gyri']),
    'g-frontal-superior': giro('Giro frontal superior', ['Superior_frontal_gyrus']),
