      actividad: { tipo: 'comparar', estructuras: ['g-precentral', 'central', 'g-poscentral', 'lateral', 'insula'], texto: 'Resalta el giro precentral, el surco central y el giro poscentral; después, el surco lateral y la ínsula de su fondo.' },
